import { IndexStatus } from '../../shared/types';

interface Props {
  status: IndexStatus;
  onIndexAll: () => void;
}

const STATUS_COLORS: Record<IndexStatus['status'], string> = {
  idle: '#888',
  indexing: '#f0ad4e',
  ready: '#5cb85c',
  error: '#d9534f',
};

export function StatusBar({ status, onIndexAll }: Props) {
  const statusColor = STATUS_COLORS[status.status] ?? '#888';
  const busy = status.status === 'indexing' && status.currentIndexed === 0;

  return (
    <div style={{
      padding: '4px 20px',
      background: '#0f1729',
      borderTop: '1px solid #0f3460',
      display: 'flex',
      alignItems: 'center',
      gap: '16px',
      fontSize: '11px',
      color: '#888',
    }}>
      <span data-testid="index-status">
        <span style={{
          display: 'inline-block',
          width: '8px',
          height: '8px',
          borderRadius: '50%',
          background: statusColor,
          marginRight: '6px',
        }} />
        Status: {status.status}
      </span>
      <span>Docs: {status.totalDocuments}</span>
      <span>Indexed: {status.currentIndexed}/{status.totalDocuments}</span>
      <span>Chunks: {status.totalChunks}</span>
      {status.lastIndexed && (
        <span>Last activity: {new Date(status.lastIndexed).toLocaleTimeString()}</span>
      )}
      <button
        onClick={onIndexAll}
        disabled={busy || status.totalDocuments === 0}
        style={{
          marginLeft: 'auto',
          fontSize: '11px',
          padding: '2px 8px',
          background: 'transparent',
          color: '#aaa',
          border: '1px solid #0f3460',
          borderRadius: '3px',
          cursor: 'pointer',
        }}
      >
        Index all
      </button>
    </div>
  );
}

